changeSet.sql:
-- Per-country, per-field reporting (the most common query) CREATE INDEX TFPM_ADDR_ENRICH.IX_ATTR_COUNTRY_FIELD ON TFPM_ADDR_ENRICH.FIELD_ATTRIBUTIONS (COUNTRY_HINT, FIELD_NAME, CREATED_AT) LOCAL;
-- Structurer-contribution analysis ("who's winning what") CREATE INDEX TFPM_ADDR_ENRICH.IX_ATTR_SELECTED ON TFPM_ADDR_ENRICH.FIELD_ATTRIBUTIONS (WAS_SELECTED, COUNTRY_HINT, FIELD_NAME, STRUCTURER_NAME) LOCAL;
-- Lookup by RESULT_ID (drill-down from STRUCTURING_RESULTS row) CREATE INDEX TFPM_ADDR_ENRICH.IX_ATTR_RESULT ON TFPM_ADDR_ENRICH.FIELD_ATTRIBUTIONS (RESULT_ID) LOCAL;

rollback.sql:
DROP INDEX TFPM_ADDR_ENRICH.IX_ATTR_RESULT;
DROP INDEX TFPM_ADDR_ENRICH.IX_ATTR_SELECTED;
DROP INDEX TFPM_ADDR_ENRICH.IX_ATTR_COUNTRY_FIELD;

changeSet.sql:
COMMENT ON TABLE TFPM_ADDR_ENRICH.FIELD_ATTRIBUTIONS IS
    'Per-field attribution. One row per (result,field,structurer). Denormalised for SQL reporting. See docs/ACCURACY_MEASUREMENT.md.';
COMMENT ON COLUMN TFPM_ADDR_ENRICH.FIELD_ATTRIBUTIONS.WAS_SELECTED IS
    'Y if the FieldMerger picked this contribution for the final result; N otherwise.';
COMMENT ON COLUMN TFPM_ADDR_ENRICH.FIELD_ATTRIBUTIONS.RAW_CONFIDENCE IS
    'Raw confidence as reported by the structurer, BEFORE calibration. Useful for calibrator retuning.';
COMMENT ON COLUMN TFPM_ADDR_ENRICH.FIELD_ATTRIBUTIONS.STRUCTURER_VERSION IS
    'Version string e.g. libpostal-1.0.0, llm-gpt-4o-2024-08-06. Required for regression analysis after model swaps.';
